                return [x[1]]
            if x[0]=='add_exception' and len(x)>2:
                return exceptions(x[1])+[x[2]]
        return []
    def make_exceptions(xs):
        clean=[]
        for x in xs:
            if x not in clean:
                clean.append(x)
        if not clean:
            return ['no_exceptions']
        v=['exception_set',clean[0]]
        for x in clean[1:]:
            v=['add_exception',v,x]
        return v
    def branch(action,wanted):
        return isinstance(action,list) and len(action)==3 and action[0]=='action_alternative' and (action[1]==wanted or action[2]==wanted)
    if isinstance(term,list) and len(term)==5 and term[0]=='retention_permission':
